/** @module local_autobrowsertimezone/timezone */
define("local_autobrowsertimezone/timezone",["core/ajax","core/notification"],function(Ajax,Notification){function getBrowserTimezone(){try{if("undefined"==typeof Intl||"function"!=typeof Intl.DateTimeFormat)return"";return String(Intl.DateTimeFormat().resolvedOptions().timeZone||"").trim()}catch(e){return""}}function markAttempt(key){try{if("1"===window.sessionStorage.getItem(key))return false;window.sessionStorage.setItem(key,"1")}catch(e){}return true}return{init:function(config){var safeConfig=config||{},browserTimezone=getBrowserTimezone(),currentTimezone=String(safeConfig.currentTimezone||"99");if(!browserTimezone||browserTimezone===currentTimezone)return;var attemptKey=["local_autobrowsertimezone",currentTimezone,browserTimezone].join(":");if(!markAttempt(attemptKey))return;var request={methodname:"local_autobrowsertimezone_update_timezone",args:{timezone:browserTimezone}};Ajax.call([request])[0].then(function(result){if(result.changed&&safeConfig.reload)window.location.reload();return result}).catch(Notification.exception)}}});
